import{H as e,V as t,et as n,j as r}from"./chunks/framework.ByEJxCeM.js";var i=JSON.parse(`{"title":"运算符","description":"","frontmatter":{},"headers":[],"relativePath":"python/python-basics/operators.md","filePath":"python/python-basics/operators.md"}`),a={name:`python/python-basics/operators.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="运算符" tabindex="-1">运算符 <a class="header-anchor" href="#运算符" aria-label="Permalink to “运算符”">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to “目标”">​</a></h2><ul><li>算数运算符</li><li>比较（关系）运算符</li><li>逻辑运算符</li><li>赋值运算符</li><li>运算符的优先级</li></ul><p>数学符号表链接：<a href="https://zh.wikipedia.org/wiki/%E6%95%B0%E5%AD%A6%E7%AC%A6%E5%8F%B7%E8%A1%A8" target="_blank" rel="noreferrer">https://zh.wikipedia.org/wiki/数学符号表</a></p><h2 id="_01-算数运算符" tabindex="-1">01. 算数运算符 <a class="header-anchor" href="#_01-算数运算符" aria-label="Permalink to “01. 算数运算符”">​</a></h2><ul><li>是完成基本的算术运算使用的符号，用来处理四则运算</li></ul><table tabindex="0"><thead><tr><th style="text-align:center;">运算符</th><th style="text-align:center;">描述</th><th>实例</th></tr></thead><tbody><tr><td style="text-align:center;">+</td><td style="text-align:center;">加</td><td>10 + 20 = 30</td></tr><tr><td style="text-align:center;">-</td><td style="text-align:center;">减</td><td>10 - 20 = -10</td></tr><tr><td style="text-align:center;">*</td><td style="text-align:center;">乘</td><td>10 * 20 = 200</td></tr><tr><td style="text-align:center;">/</td><td style="text-align:center;">除</td><td>10 / 20 = 0.5</td></tr><tr><td style="text-align:center;">//</td><td style="text-align:center;">取整除</td><td>返回除法的整数部分（商） 9 // 2 输出结果 4</td></tr><tr><td style="text-align:center;">%</td><td style="text-align:center;">取余数</td><td>返回除法的余数 9 % 2 = 1</td></tr><tr><td style="text-align:center;">**</td><td style="text-align:center;">幂</td><td>又称次方、乘方，2 ** 3 = 8</td></tr></tbody></table><ul><li>在 Python 中 <code>*</code> 运算符还可以用于字符串，计算结果就是字符串重复指定次数的结果</li></ul><div class="language-python"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">In [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-&quot;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Out[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;----------------------------------------&#39;</span></span></code></pre></div><h2 id="_02-比较-关系-运算符" tabindex="-1">02. 比较（关系）运算符 <a class="header-anchor" href="#_02-比较-关系-运算符" aria-label="Permalink to “02. 比较（关系）运算符”">​</a></h2><table tabindex="0"><thead><tr><th>运算符</th><th>描述</th></tr></thead><tbody><tr><td>==</td><td>检查两个操作数的值是否 <strong>相等</strong>，如果是，则条件成立，返回 True</td></tr><tr><td>!=</td><td>检查两个操作数的值是否 <strong>不相等</strong>，如果是，则条件成立，返回 True</td></tr><tr><td>&gt;</td><td>检查左操作数的值是否 <strong>大于</strong> 右操作数的值，如果是，则条件成立，返回 True</td></tr><tr><td>&lt;</td><td>检查左操作数的值是否 <strong>小于</strong> 右操作数的值，如果是，则条件成立，返回 True</td></tr><tr><td>&gt;=</td><td>检查左操作数的值是否 <strong>大于或等于</strong> 右操作数的值，如果是，则条件成立，返回 True</td></tr><tr><td>&lt;=</td><td>检查左操作数的值是否 <strong>小于或等于</strong> 右操作数的值，如果是，则条件成立，返回 True</td></tr></tbody></table><blockquote><p>Python 2.x 中判断 <strong>不等于</strong> 还可以使用 <code>&lt;&gt;</code> 运算符</p><p><code>!=</code> 在 Python 2.x 中同样可以用来判断 <strong>不等于</strong></p></blockquote><h2 id="_03-逻辑运算符" tabindex="-1">03. 逻辑运算符 <a class="header-anchor" href="#_03-逻辑运算符" aria-label="Permalink to “03. 逻辑运算符”">​</a></h2><table tabindex="0"><thead><tr><th>运算符</th><th>逻辑表达式</th><th>描述</th></tr></thead><tbody><tr><td>and</td><td>x and y</td><td>只有 x 和 y 的值都为 True，才会返回 True<br>否则只要 x 或者 y 有一个值为 False，就返回 False</td></tr><tr><td>or</td><td>x or y</td><td>只要 x 或者 y 有一个值为 True，就返回 True<br>只有 x 和 y 的值都为 False，才会返回 False</td></tr><tr><td>not</td><td>not x</td><td>如果 x 为 True，返回 False<br>如果 x 为 False，返回 True</td></tr></tbody></table><h2 id="_04-赋值运算符" tabindex="-1">04. 赋值运算符 <a class="header-anchor" href="#_04-赋值运算符" aria-label="Permalink to “04. 赋值运算符”">​</a></h2><ul><li>在 Python 中，使用 <code>=</code> 可以给变量赋值</li><li>在算术运算时，为了简化代码的编写，<code>Python</code> 还提供了一系列的 与 <strong>算术运算符</strong> 对应的 <strong>赋值运算符</strong></li><li>注意：<strong>赋值运算符中间不能使用空格</strong></li></ul><table tabindex="0"><thead><tr><th>运算符</th><th>描述</th><th>实例</th></tr></thead><tbody><tr><td>=</td><td>简单的赋值运算符</td><td>c = a + b 将 a + b 的运算结果赋值为 c</td></tr><tr><td>+=</td><td>加法赋值运算符</td><td>c += a 等效于 c = c + a</td></tr><tr><td>-=</td><td>减法赋值运算符</td><td>c -= a 等效于 c = c - a</td></tr><tr><td>*=</td><td>乘法赋值运算符</td><td>c *= a 等效于 c = c * a</td></tr><tr><td>/=</td><td>除法赋值运算符</td><td>c /= a 等效于 c = c / a</td></tr><tr><td>//=</td><td>取整除赋值运算符</td><td>c //= a 等效于 c = c // a</td></tr><tr><td>%=</td><td>取 <strong>模</strong> (余数)赋值运算符</td><td>c %= a 等效于 c = c % a</td></tr><tr><td>**=</td><td>幂赋值运算符</td><td>c **= a 等效于 c = c ** a</td></tr></tbody></table><h2 id="_05-运算符的优先级" tabindex="-1">05. 运算符的优先级 <a class="header-anchor" href="#_05-运算符的优先级" aria-label="Permalink to “05. 运算符的优先级”">​</a></h2><ul><li>以下表格的算数优先级由高到最低顺序排列</li></ul><table tabindex="0"><thead><tr><th>运算符</th><th>描述</th></tr></thead><tbody><tr><td>**</td><td>幂 (最高优先级)</td></tr><tr><td>* / % //</td><td>乘、除、取余数、取整除</td></tr><tr><td>+ -</td><td>加法、减法</td></tr><tr><td>&lt;= &lt; &gt; &gt;=</td><td>比较运算符</td></tr><tr><td>== !=</td><td>等于运算符</td></tr><tr><td>= %= /= //= -= += *= **=</td><td>赋值运算符</td></tr><tr><td>not or and</td><td>逻辑运算符</td></tr></tbody></table>`,20)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};